#!/usr/bin/env python3
"""go-task の Taskfile を持つ ghq リポジトリを一覧する Script Filter。"""
import json, os, subprocess, sys

GHQ = "/etc/profiles/per-user/yoshihiko/bin/ghq"
TASKFILE_NAMES = ("Taskfile.yml", "Taskfile.yaml", "taskfile.yml", "taskfile.yaml")

query = (sys.argv[1] if len(sys.argv) > 1 else "").strip().lower()

# alfred_workflow_data が未設定なら config なし扱い（os.getcwd() へはフォールバックしない）
wf_data = os.getenv("alfred_workflow_data")
cfg = {"extras": [], "overrides": {}, "excludes": [], "terminal": []}
if wf_data:
    try:
        with open(os.path.join(wf_data, "config.json"), "r", encoding="utf-8") as f:
            cfg.update(json.load(f))
    except FileNotFoundError:
        pass
    except Exception:
        pass

excludes = cfg.get("excludes", [])
overrides = cfg.get("overrides", {})

try:
    out = subprocess.check_output([GHQ, "list", "--full-path"], text=True)
    repos = [l for l in out.strip().splitlines() if l]
except Exception:
    repos = []

try:
    ghq_root = subprocess.check_output([GHQ, "root"], text=True).strip()
except Exception:
    ghq_root = ""

items = []

for full_path in repos:
    if not any(os.path.isfile(os.path.join(full_path, n)) for n in TASKFILE_NAMES):
        continue

    rel = full_path.replace(ghq_root + "/", "", 1) if ghq_root else full_path
    parts = rel.split("/")
    repo_key = "/".join(parts[2:]) if len(parts) > 2 else rel
    basename = os.path.basename(full_path.rstrip("/"))

    if repo_key in excludes or basename in excludes:
        continue

    name = overrides.get(repo_key, {}).get("name", basename)

    if query and query not in f"{name} {repo_key} {full_path}".lower():
        continue

    items.append({
        "title": name,
        "subtitle": full_path,
        "arg": full_path,
        "variables": {"project_name": name, "project_dir": full_path},
    })

# extras（ghq 管理外のプロジェクト。Taskfile の有無は検査せず config を信頼する）
for ex in cfg.get("extras", []):
    path = ex.get("path", "")
    name = ex.get("name", os.path.basename(path.rstrip("/")))
    if query and query not in f"{name} {path}".lower():
        continue
    items.append({
        "title": name,
        "subtitle": path,
        "arg": path,
        "variables": {"project_name": name, "project_dir": path},
    })

if not items:
    items = [{"title": "Taskfile を持つプロジェクトが見つかりません", "subtitle": query, "valid": False}]

print(json.dumps({"items": items}, ensure_ascii=False))

#!/usr/bin/env python3
"""選択したプロジェクトの go-task タスク（desc ありのみ）を一覧する Script Filter。"""
import hashlib
import json
import os
import re
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor

TASK = "/etc/profiles/per-user/yoshihiko/bin/task"
TASKFILE_NAMES = ("Taskfile.yml", "Taskfile.yaml", "taskfile.yml", "taskfile.yaml")

query = (sys.argv[1] if len(sys.argv) > 1 else "").strip().lower()
project_name = os.getenv("project_name", "")
project_dir = os.getenv("project_dir", "")

if not project_dir:
    print(json.dumps({"items": [{"title": "プロジェクトが取得できません", "valid": False}]}, ensure_ascii=False))
    raise SystemExit


def is_project_root_taskfile(taskfile_path):
    if not taskfile_path:
        return True
    return any(
        os.path.abspath(taskfile_path) == os.path.abspath(os.path.join(project_dir, n))
        for n in TASKFILE_NAMES
    )


try:
    out = subprocess.check_output(
        [TASK, "--list", "--json"], text=True, cwd=project_dir, timeout=10, stderr=subprocess.DEVNULL
    )
    tasks = json.loads(out).get("tasks", [])
except Exception:
    tasks = None

if tasks is None:
    print(json.dumps({
        "items": [{"title": "タスク一覧の取得に失敗しました", "subtitle": project_dir, "valid": False}]
    }, ensure_ascii=False))
    raise SystemExit

desc_tasks = [t for t in tasks if t.get("name") and t.get("desc")]

# --- vars / requires / CLI_ARGS 抽出（重い処理なので Taskfile の mtime でキャッシュする） ---

_FILE_LINES_CACHE = {}


def read_lines(path):
    if path not in _FILE_LINES_CACHE:
        try:
            with open(path, "r", encoding="utf-8") as f:
                _FILE_LINES_CACHE[path] = f.read().splitlines()
        except OSError:
            _FILE_LINES_CACHE[path] = []
    return _FILE_LINES_CACHE[path]


def task_body_lines(lines, start_idx):
    """taskfile 上でタスク定義が始まる行から、次のトップレベル要素の手前までを返す"""
    if start_idx >= len(lines):
        return []
    indent = len(lines[start_idx]) - len(lines[start_idx].lstrip(" "))
    end_idx = len(lines)
    for j in range(start_idx + 1, len(lines)):
        line = lines[j]
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        cur_indent = len(line) - len(line.lstrip(" "))
        if cur_indent <= indent:
            end_idx = j
            break
    return lines[start_idx:end_idx]


def parse_summary_vars(text):
    """`task --summary` の出力から vars の既定値と requires の必須変数名を抜き出す"""
    lines = text.splitlines()

    def find_top(label):
        for i, l in enumerate(lines):
            if l == f"{label}:":
                return i
        return None

    vars_idx = find_top("vars")
    requires_idx = find_top("requires")
    commands_idx = find_top("commands")

    var_defaults = {}
    if vars_idx is not None:
        candidates = [i for i in (requires_idx, commands_idx) if i is not None and i > vars_idx]
        end = min(candidates) if candidates else len(lines)
        for l in lines[vars_idx + 1:end]:
            if not l.strip():
                continue
            m = re.match(r'^  ([A-Za-z_][A-Za-z0-9_]*): (.*)$', l)
            if m:
                val = m.group(2).strip()
                if val.startswith('"') and val.endswith('"') and len(val) >= 2:
                    val = val[1:-1]
                var_defaults[m.group(1)] = val

    required_vars = []
    if requires_idx is not None:
        end = commands_idx if commands_idx is not None else len(lines)
        for l in lines[requires_idx + 1:end]:
            m = re.match(r'^\s*-\s*(\S+)\s*$', l)
            if m:
                required_vars.append(m.group(1))

    return var_defaults, required_vars


def parse_own_vars(body):
    """タスク定義ブロックから、タスク自身が持つ vars: 直下のキーと
    requires: vars: のキーだけを抜き出す（include 元やトップレベルの vars は含めない）"""
    if len(body) < 2:
        return set()

    child_indent = None
    for line in body[1:]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        child_indent = len(line) - len(line.lstrip(" "))
        break
    if child_indent is None:
        return set()

    def own_section(label):
        """child_indent 上にある `label:` 行を探し、(同じ行の残り, より深い内側の行) を返す"""
        for i, line in enumerate(body):
            if len(line) - len(line.lstrip(" ")) != child_indent:
                continue
            stripped = line.strip()
            if stripped != f"{label}:" and not stripped.startswith(f"{label}:"):
                continue
            inline = stripped[len(label) + 1:].strip()
            inner = []
            for j in range(i + 1, len(body)):
                l2 = body[j]
                s2 = l2.strip()
                if not s2 or s2.startswith("#"):
                    continue
                if len(l2) - len(l2.lstrip(" ")) <= child_indent:
                    break
                inner.append(l2)
            return inline, inner
        return "", []

    names = set()

    _, vars_inner = own_section("vars")
    if vars_inner:
        vars_indent = len(vars_inner[0]) - len(vars_inner[0].lstrip(" "))
        for l in vars_inner:
            if len(l) - len(l.lstrip(" ")) != vars_indent:
                continue
            m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*):', l.strip())
            if m:
                names.add(m.group(1))

    _, requires_inner = own_section("requires")
    if requires_inner:
        req_indent = len(requires_inner[0]) - len(requires_inner[0].lstrip(" "))
        for i, l in enumerate(requires_inner):
            if len(l) - len(l.lstrip(" ")) != req_indent:
                continue
            stripped = l.strip()
            if stripped != "vars:" and not stripped.startswith("vars:"):
                continue
            inline = stripped[len("vars:"):].strip()
            if inline.startswith("[") and inline.endswith("]"):
                for item in inline[1:-1].split(","):
                    item = item.strip()
                    if item:
                        names.add(item)
            else:
                for l2 in requires_inner[i + 1:]:
                    s2 = l2.strip()
                    if not s2:
                        continue
                    if len(l2) - len(l2.lstrip(" ")) <= req_indent:
                        break
                    m2 = re.match(r'^-\s*(\S+)', s2)
                    if m2:
                        names.add(m2.group(1))
            break

    return names


def compute_task_meta(t):
    name = t["name"]
    try:
        summary_out = subprocess.check_output(
            [TASK, "--summary", name], text=True, cwd=project_dir, timeout=5, stderr=subprocess.DEVNULL
        )
    except Exception:
        summary_out = ""

    # `task --summary` の vars/requires にはトップレベル vars や include 元の変数も
    # 混ざるため、既定値の取得にのみ使い、ヒント対象はタスク自身の vars に絞り込む
    var_defaults, required_vars = parse_summary_vars(summary_out)

    loc = t.get("location", {}) or {}
    taskfile = loc.get("taskfile", "")
    line = loc.get("line")
    cli_args = False
    own_vars = set()
    if taskfile and line:
        lines = read_lines(taskfile)
        idx = line - 1
        if 0 <= idx < len(lines):
            body = task_body_lines(lines, idx)
            cli_args = any(".CLI_ARGS" in l for l in body)
            own_vars = parse_own_vars(body)

    var_defaults = {k: v for k, v in var_defaults.items() if k in own_vars}
    required_vars = [k for k in required_vars if k in own_vars]

    return {"defaults": var_defaults, "required": required_vars, "cli_args": cli_args}


# --- キャッシュ（$alfred_workflow_cache 配下、Taskfile 群の mtime をキーにする） ---

cache_dir = os.getenv("alfred_workflow_cache")
cache_path = None
cached_data = {}
cache_key = None

if cache_dir:
    digest = hashlib.sha1(project_dir.encode("utf-8")).hexdigest()[:16]
    cache_path = os.path.join(cache_dir, "task_vars", f"{digest}.json")

    taskfile_paths = sorted({
        t.get("location", {}).get("taskfile", "") for t in desc_tasks if t.get("location")
    })
    mtimes = {}
    for p in taskfile_paths:
        if not p:
            continue
        try:
            mtimes[p] = os.path.getmtime(p)
        except OSError:
            mtimes[p] = 0
    # own-vars 絞り込みロジックを追加したため、キャッシュ形式のバージョンを混ぜて
    # 旧ロジックで保存された古いキャッシュを無効化する
    VARS_ALGO_VERSION = 2
    cache_key = json.dumps({"algo": VARS_ALGO_VERSION, "mtimes": mtimes}, sort_keys=True)

    try:
        with open(cache_path, "r", encoding="utf-8") as f:
            saved = json.load(f)
        if saved.get("cache_key") == cache_key:
            cached_data = saved.get("data", {})
    except Exception:
        cached_data = {}

to_compute = [t for t in desc_tasks if t["name"] not in cached_data]
computed = {}
if to_compute:
    workers = min(12, max(4, len(to_compute)))
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = {ex.submit(compute_task_meta, t): t["name"] for t in to_compute}
        for fut in futures:
            name = futures[fut]
            try:
                computed[name] = fut.result()
            except Exception:
                computed[name] = {"defaults": {}, "required": [], "cli_args": False}

all_meta = dict(cached_data)
all_meta.update(computed)

if cache_path and computed:
    try:
        os.makedirs(os.path.dirname(cache_path), exist_ok=True)
        with open(cache_path, "w", encoding="utf-8") as f:
            json.dump({"cache_key": cache_key, "data": all_meta}, f, ensure_ascii=False)
    except OSError:
        pass


def build_hint(meta):
    parts = []
    seen = set()
    for k, v in meta.get("defaults", {}).items():
        seen.add(k)
        parts.append(f"{k}={v}")
    for k in meta.get("required", []):
        if k not in seen:
            parts.append(f"{k}=<必須>")
    hint = " ".join(parts)
    if meta.get("cli_args"):
        hint = (hint + " -- <args>").strip()
    return f"⌨ {hint}" if hint else ""


items = []
for t in desc_tasks:
    name = t.get("name", "")
    desc = t.get("desc", "")
    if query and query not in f"{name} {desc}".lower():
        continue

    taskfile = t.get("location", {}).get("taskfile", "")
    subtitle = desc
    if not is_project_root_taskfile(taskfile):
        subtitle += f" [{os.path.relpath(taskfile, project_dir)}]"

    meta = all_meta.get(name, {"defaults": {}, "required": [], "cli_args": False})
    hint = build_hint(meta)
    if hint:
        subtitle += f"  {hint}"

    summary_text = (t.get("summary") or "").strip()
    task_summary = summary_text.splitlines()[0] if summary_text else ""

    items.append({
        "title": f"{project_name} › {name}",
        "subtitle": subtitle,
        "arg": name,
        "variables": {
            "project_name": project_name,
            "project_dir": project_dir,
            "task_name": name,
            "task_vars": json.dumps(meta, ensure_ascii=False),
            "task_summary": task_summary,
        },
    })

if not items:
    items = [{"title": "desc 付きのタスクが見つかりません", "subtitle": project_dir, "valid": False}]

print(json.dumps({"items": items}, ensure_ascii=False))

#!/usr/bin/env python3
"""バックグラウンド実行 / ターミナル実行を選ばせる確認 Script Filter。
入力欄の文字列は go-task に渡す引数（KEY=VALUE / -- 以降の CLI_ARGS）として扱う。
"""
import json
import os
import shlex
import sys

project_name = os.getenv("project_name", "")
project_dir = os.getenv("project_dir", "")
task_name = os.getenv("task_name", "")
task_summary = os.getenv("task_summary", "")
task_vars_raw = os.getenv("task_vars", "")

raw_args = sys.argv[1] if len(sys.argv) > 1 else ""

if not project_dir or not task_name:
    print(json.dumps({
        "items": [{"title": "プロジェクトまたはタスクが取得できません", "valid": False}]
    }, ensure_ascii=False))
    raise SystemExit

try:
    task_vars = json.loads(task_vars_raw) if task_vars_raw else {}
except Exception:
    task_vars = {}

required_vars = task_vars.get("required", []) if isinstance(task_vars, dict) else []
var_defaults = task_vars.get("defaults", {}) if isinstance(task_vars, dict) else {}
cli_args_used = bool(task_vars.get("cli_args")) if isinstance(task_vars, dict) else False


def build_hint():
    parts = []
    seen = set()
    for k, v in var_defaults.items():
        seen.add(k)
        parts.append(f"{k}={v}")
    for k in required_vars:
        if k not in seen:
            parts.append(f"{k}=<必須>")
    hint = " ".join(parts)
    if cli_args_used:
        hint = (hint + " -- <args>").strip()
    return f"⌨ {hint}" if hint else ""


# --- 引数のトークン化 ---
parse_error = None
tokens = []
if raw_args.strip():
    try:
        tokens = shlex.split(raw_args)
    except ValueError as e:
        parse_error = str(e)

if parse_error is not None:
    print(json.dumps({
        "items": [{
            "title": f"引数を解析できません: {raw_args}",
            "subtitle": f"入力を見直してください（{parse_error}）",
            "valid": False,
        }]
    }, ensure_ascii=False))
    raise SystemExit

# "--" より前のトークンから KEY=VALUE で渡された変数名を集める
supplied_vars = set()
for tok in tokens:
    if tok == "--":
        break
    if "=" in tok:
        key = tok.split("=", 1)[0]
        if key:
            supplied_vars.add(key)

missing = [v for v in required_vars if v not in supplied_vars and v not in var_defaults]

args_display = raw_args.strip()
title_suffix = f" {args_display}" if args_display else ""

if missing:
    print(json.dumps({
        "items": [{
            "title": f"実行: {project_name} › {task_name}{title_suffix}",
            "subtitle": f"{', '.join(missing)} が未指定です",
            "valid": False,
        }]
    }, ensure_ascii=False))
    raise SystemExit

wf_data = os.getenv("alfred_workflow_data")
terminal_list = []
if wf_data:
    try:
        with open(os.path.join(wf_data, "config.json"), "r", encoding="utf-8") as f:
            terminal_list = json.load(f).get("terminal", [])
    except Exception:
        terminal_list = []

prefer_terminal = (
    f"{project_name}/{task_name}" in terminal_list or f"{project_name}/*" in terminal_list
)

if task_summary:
    base_subtitle = task_summary
else:
    hint = build_hint()
    guidance = "入力欄で KEY=VALUE や -- 引数 を指定"
    base_subtitle = f"{hint} / {guidance}" if hint else guidance

task_args_json = json.dumps(tokens, ensure_ascii=False)


def make_item(title, mode, mode_detail):
    return {
        "title": title,
        "subtitle": f"{base_subtitle} / {mode_detail}",
        "arg": mode,
        "variables": {
            "project_name": project_name,
            "project_dir": project_dir,
            "task_name": task_name,
            "mode": mode,
            "task_args": task_args_json,
        },
    }


bg_detail = f"バックグラウンドで実行し通知 / {project_dir}"
if prefer_terminal:
    bg_detail += " ⚠ 設定でターミナル推奨"

bg = make_item(f"実行: {project_name} › {task_name}{title_suffix}", "background", bg_detail)
term = make_item(
    f"ターミナルで実行: {project_name} › {task_name}{title_suffix}",
    "terminal",
    "tmux \"tasks\" セッションで実行 / 対話・sudo・長時間向け",
)

items = [term, bg] if prefer_terminal else [bg, term]

print(json.dumps({"items": items}, ensure_ascii=False))
